px; }\\n.xx-info-text { font-size: 12px; color: var(--text-soft); flex: 1; }\\n.xx-info-side-btn {\\n  font-size: 10px; font-family: inherit; cursor: pointer;\\n  padding: 3px 9px; border-radius: 10px;\\n  border: 1px solid var(--divider);\\n  background: rgba(0,0,0,0.012); color: var(--text-muted);\\n  letter-spacing: 1px; transition: all 0.2s; white-space: nowrap; flex-shrink: 0;\\n}\\n#ac-content.dark .xx-info-side-btn { background: rgba(255,255,255,0.015); }\\n.xx-info-side-btn:hover,\\n.xx-info-action-row .investigate-btn:hover { border-color: var(--jade-deep); color: var(--jade-deep); background: rgba(90,144,120,0.06); box-shadow: 0 0 8px rgba(90,144,120,0.08); }\\n/* 鍓嶄笘浠婄敓鎸夐挳鍦ㄤ粰渚犱腑涓?xx-info-side-btn 椋庢牸缁熶竴 */\\n.xx-info-action-row .investigate-btn {\\n  font-size: 10px; font-family: inherit; cursor: pointer;\\n  padding: 3px 9px; border-radius: 10px;\\n  border: 1px solid var(--divider);\\n  background: rgba(0,0,0,0.012); color: var(--text-muted);\\n  letter-spacing: 1px; transition: all 0.2s; white-space: nowrap; flex-shrink: 0;\\n}\\n#ac-content.dark .xx-info-action-row .investigate-btn { background: rgba(255,255,255,0.015); }\\n\\n/* 閬撳績钂欏皹杩涘害鏉?*/\\n.xx-daoheart-block {\\n  display: flex; align-items: center; gap: 10px;\\n  margin: 10px 0; padding: 9px 14px;\\n  background: rgba(0,0,0,0.02); border-radius: 12px;\\n}\\n#ac-content.dark .xx-daoheart-block { background: rgba(255,255,255,0.02); }\\n.xx-daoheart-label { font-family: \\'Ma Shan Zheng\\',\\'Kaiti SC\\',\\'STKaiti\\',\\'KaiTi\\',\\'楷体\\', serif; font-size: 11px; color: var(--text-muted); letter-spacing: 2px; flex-shrink: 0; }\\n.xx-daoheart-track { flex: 1; height: 7px; border-radius: 4px; background: var(--divider-light); position: relative; overflow: visible; }\\n.xx-daoheart-fill { height: 100%; border-radius: 4px; transition: width 0.8s ease, background 0.8s; position: relative; }\\n.xx-daoheart-fill::after { content: \\'\\'; position: absolute; top: 0; left: 0; right: 0; height: 45%; background: linear-gradient(180deg, rgba(255,255,255,0.35), transparent); border-radius: 4px; }\\n.xx-daoheart-fill.clear { background: linear-gradient(90deg, var(--jade-deep), var(--spirit)); }\\n.xx-daoheart-fill.mid { background: linear-gradient(90deg, var(--jade-deep), var(--gold), var(--cinnabar)); }\\n.xx-daoheart-fill.corrupt { background: linear-gradient(90deg, var(--gold), var(--cinnabar), #8a1a1a); }\\n.xx-daoheart-nodes { position: absolute; top: -2px; left: 0; right: 0; bottom: -2px; display: flex; justify-content: space-between; pointer-events: none; padding: 0 1px; }\\n.xx-daoheart-node { width: 4px; height: 4px; border-radius: 50%; background: var(--divider); transition: all 0.5s; }\\n.xx-daoheart-node.lit { background: var(--gold-bright); box-shadow: 0 0 5px var(--gold-pale); }\\n.xx-daoheart-node.broken { background: var(--cinnabar); box-shadow: 0 0 4px var(--cinnabar-light); }\\n.xx-daoheart-pct { font-size: 11px; font-weight: 600; letter-spacing: 1px; min-width: 55px; text-align: right; }\\n.xx-daoheart-pct.low { color: var(--jade-deep); }\\n.xx-daoheart-pct.mid { color: var(--gold-deep); }\\n.xx-daoheart-pct.high { color: var(--cinnabar-deep); }\\n\\n/* 璇︽儏tab */\\n.xx-detail-tabs { display: flex; gap: 6px; margin: 10px 0 8px; }\\n.xx-detail-tab {\\n  padding: 4px 12px; border-radius: 12px; border: 1px solid var(--divider);\\n  background: transparent; cursor: pointer; font-family: inherit; font-size: 11px;\\n  color: var(--text-muted); letter-spacing: 1px; transition: all 0.2s;\\n}\\n.xx-detail-tab:hover { border-color: var(--jade-light); color: var(--jade-deep); }\\n.xx-detail-tab.active-switch { border-color: var(--jade-deep); color: var(--jade-deep); background: rgba(90,144,120,0.08); box-shadow: 0 0 10px rgba(90,144,120,0.1); }\\n\\n/* 鍗曞垪鍒楄〃 */\\n.xx-detail-list { display: flex; flex-direction: column; gap: 4px; }\\n.xx-detail-item {\\n  display: flex; gap: 8px; padding: 6px 10px; border-radius: 8px; font-size: 11px;\\n  background: rgba(0,0,0,0.0