e":{"type":"counter-rows","table":"纪要表","value":10},"rarity":1},{"id":"chronicle_30","cat":"纪事","name":"起居注官","intro":"累计记录 30 条纪要","趣评":"起居注都没你记得勤呢～呵呵，连喝水吃饭的间隙都成了档案里的一行，你在上面写的时候大概没想过，这些琐碎也是历史呀。","observe":{"type":"counter-rows","table":"纪要表","value":30},"rarity":1},{"id":"chronicle_100","cat":"纪事","name":"青史留痕","intro":"累计记录 100 条纪要","趣评":"堆起来够编一本起居注了呢～若干年后翻出来，怕是自己都不好意思看吧？人家倒是乐意替你保管这份沉甸甸的黑历史哦。","observe":{"type":"counter-rows","table":"纪要表","value":100},"rarity":2},{"id":"chronicle_total_100","cat":"纪事","name":"青史连篇","intro":"累计记录 100 条纪要（跨对话总计）","趣评":"换了几任主角了，纪要倒是一本接一本地垒了上来呀～你这家伙，该不会以此为乐吧？姐姐翻着翻着都快理不清时间线了呢，真是的。","observe":{"type":"chat-snapshot-delta","counter":"chronicleTotalCount","getter":"chronicleRowCount","value":100},"rarity":1},{"id":"chronicle_total_300","cat":"纪事","name":"汗牛充栋","intro":"累计记录 300 条纪要（跨对话总计）","趣评":"档案馆都快塞不下了呀～你这辈子要是出回忆录，光目录就得印好几页，人家自荐当你的责任编辑好了，稿费四六分哦。","observe":{"type":"chat-snapshot-delta","counter":"chronicleTotalCount","getter":"chronicleRowCount","value":300},"rarity":1},{"id":"chronicle_total_500","cat":"纪事","name":"万世流芳","intro":"累计记录 500 条纪要（跨对话总计）","趣评":"这墨迹怕是要汇成一座纸上帝国了呀～呵呵，后人考据你的人生大概比考据正史还有意思，人家很期待那一天呢。","observe":{"type":"chat-snapshot-delta","counter":"chronicleTotalCount","getter":"chronicleRowCount","value":500},"rarity":2},{"id":"chronicle_total_1000","cat":"纪事","name":"青史永镌","intro":"累计记录 1000 条纪要（跨对话总计）","趣评":"千篇纪要，多少离合悲欢都凝在这些字里了呀～姐姐我一页页翻过去，竟觉得自己像个守墓人……不过墓里埋的都是活的记忆，倒也值了呢。","observe":{"type":"chat-snapshot-delta","counter":"chronicleTotalCount","getter":"chronicleRowCount","value":1000},"rarity":2},{"id":"check_difficulty_diverse_4","cat":"收集","name":"难易有谱","intro":"当前检定建议中出现 4 种不同难度","趣评":"从唾手可得到难如登天都替你排好了呢～人家就欣赏这种心里有数的孩子，不过选项再多也得真去选一个呀，光看不练可不算本事哦。","observe":{"type":"collection","table":"检定建议表","col":"检定难度","value":4},"_note":"B. 检定建议表","rarity":1},{"id":"check_difficulty_diverse_5","cat":"收集","name":"步步为营","intro":"当前检定建议中出现 5 种不同难度","趣评":"五种台阶一字排开，跟人生菜单似的呢～呵呵，最难那道你大概率会绕过去吧？姐姐看得透透的，不过偶尔选一次难的也不错嘛。","observe":{"type":"collection","table":"检定建议表","col":"检定难度","value":5},"rarity":1},{"id":"check_all_zero","cat":"隐藏","name":"万事顺遂","intro":"当前检定建议中至少 3 项难度为 0（无需检定）","趣评":"今天运气好得不像话呢～全是白送的通路，连老天都懒得给你设坎……啧，这种日子多来几天，人就废了哦，笨蛋。","observe":{"type":"counter-rows","table":"检定建议表","filter":{"col":"检定难度","equals":"0"},"value":3},"hidden":true,"rarity":0},{"id":"check_all_hard","cat":"隐藏","name":"荆棘满途","intro":"当前检定建议中至少 3 项难度为 5（近乎不可能）","趣评":"三条绝路整整齐齐地列在那儿呢～人家都不知道该佩服你运气差还是夸你胆量大了，这种局也敢接着，真是个疯孩子呀。","observe":{"type":"counter-rows","table":"检定建议表","filter":{"col":"检定难度","equals":"5"},"value":3},"hidden":true,"rarity":0},{"id":"check_all_five_same","cat":"隐藏","name":"五岳同高","intro":"当前检定建议全部 5 项难度相同","趣评":"五条路全是一个坡度，老天爷今天大概是懒得分级了呀～要么全是坦途要么全是绝壁，这种极端的均匀感本身就很诡异呢，你打算闭眼选一条吗？","observe":{"type":"collection","table":"检定建议表","col":"检定难度","value":1},"hidden":true,"rarity":0},{"id":"female_emotion_happy","cat":"剧情","name":"笑靥如花","intro":"同场在场角色中有人表现出「开心」情绪","趣评":"笑得这么灿烂，倒显得你做了什么了不起的事呢～哼，省得替你高兴，啧，八成是阳光照进来有点晃眼罢了，笨蛋。","observe":{"type":"enum-state","table":"在场角色表","col":"情绪","value":"开心"},"_note":"C. 在场角色·剩余情绪","rarity":0},{"id":"female_emotion_angry","cat":"剧情","name":"怒火中烧","intro":"同场在场角色中有人表现出「愤怒」情绪","趣评":"谁把你家姑娘惹毛了呀～人家隔着表都觉得空气发烫，肇事者最好赶紧认错，不然这火怕是没那么容易灭哦。","observe":{"type":"enum-state","table":"在场角色表","col":"情绪","value":"愤怒"},"rarity":0},{"id":"female_emotion_guilty","cat":"剧情","name":"心虚如鼠","intro":"同场在场角色中有人表现出「心虚」情绪","趣评":"有人心里藏了事呢～眼神飘忽、话也说一半留一半，啧啧，这心虚的小模样倒挺可爱的，你猜她瞒的是什么？","observe":{"type":"enum-state","table":"在场角色表","col":"情绪","value":"心虚"},"rarity":0},{"id":"female_emotion_nervous","cat":"剧情","name":"如坐针毡","intro":"同场在场角色中有人表现出「紧张」情绪","趣评":"空气绷得像琴弦呢～有人紧张得手指都在绞衣角了，你呀倒是半点没察觉的样子，木头一个，真是的。","observe":{"type":"enum-state","table":"在场角色表","col":"情绪","value":"紧张"},"rarity":0},{"id":"female_emotion_disdain","cat":"剧情","name":"冷眼旁观","intro":"同场在场角色中有人表现出「不屑」情绪","趣评":"那道冷眼扫过来的时候，姐姐都替你觉得背后一凉呢～呵呵，被嫌弃的滋味怎么样？人家倒是看得津津有味的。","observe":{"type":"enum-state","table":"在场角色表","col":"情绪","value":"不屑"},"rarity":0},{"id":"female_e