nt-family: inherit;\\n  white-space: nowrap;\\n  flex-shrink: 0;\\n}\\n.cal-refresh-btn:hover {\\n  border-color: var(--ub-accent, #4a90d9);\\n  color: var(--ub-accent, #4a90d9);\\n}\\n\\n.cal-close-btn {\\n  width: 28px;\\n  height: 28px;\\n  border: 1px solid var(--ub-divider, #e0e0e0);\\n  background: transparent;\\n  color: var(--ub-text-muted, #888);\\n  font-size: 16px;\\n  cursor: pointer;\\n  display: flex;\\n  align-items: center;\\n  justify-content: center;\\n  border-radius: var(--ub-btn-radius, 4px);\\n  transition: all 0.2s;\\n  flex-shrink: 0;\\n  padding: 0;\\n  line-height: 1;\\n}\\n.cal-close-btn:hover {\\n  background: rgba(196,30,58,0.1);\\n  border-color: #c41e3a;\\n  color: #c41e3a;\\n}\\n\\n/* ═══════════════════════════════════════════════════ */\\n/*  星期标题行                                        */\\n/* ═══════════════════════════════════════════════════ */\\n.cal-weekdays {\\n  display: grid;\\n  grid-template-columns: repeat(7, 1fr);\\n  padding: 8px 4px 2px;\\n  font-size: 10px;\\n  color: var(--ub-text-muted, #888);\\n  letter-spacing: 1px;\\n}\\n.cal-weekdays span {\\n  text-align: center;\\n}\\n\\n/* ═══════════════════════════════════════════════════ */\\n/*  日期网格                                          */\\n/* ═══════════════════════════════════════════════════ */\\n.cal-grid {\\n  display: grid;\\n  grid-template-columns: repeat(7, 1fr);\\n  gap: 2px;\\n  padding: 4px 6px 8px;\\n}\\n\\n.cal-day {\\n  aspect-ratio: 1;\\n  border: 1px solid transparent;\\n  background: transparent;\\n  color: var(--ub-text, #111);\\n  font-size: 12px;\\n  cursor: pointer;\\n  display: flex;\\n  flex-direction: column;\\n  align-items: center;\\n  justify-content: center;\\n  gap: 2px;\\n  padding: 2px;\\n  border-radius: var(--ub-btn-radius, 4px);\\n  transition: all 0.15s;\\n  position: relative;\\n  font-family: inherit;\\n  min-width: 0;\\n}\\n.cal-day:hover {\\n  background: var(--ub-hover-bg, rgba(0,0,0,0.06));\\n}\\n\\n.cal-day.is-outside-month