      bs = h.indexOf('>', bs) + 1;
      var be = h.indexOf('</body>');
      var bHTML = (bs > 0 && be > bs) ? h.substring(bs, be) : '';

      // 解析 script（仅首次注入时需要）
      if (!scriptInjected) {
        var ss = h.indexOf('<script');
        ss = h.indexOf('>', ss) + 1;
        var se = h.lastIndexOf('<\/script>');
        if (ss > 0 && se > ss) sCode = h.substring(ss, se);
      }

      if (!bHTML) { injecting = false; return; }

      // 创建 wrapper
      var w = pd.createElement('div');
      w.id = 'ac-statusbar-wrapper';
      w.style.cssText = wrapCSS(c);
      w.innerHTML = bHTML;

      // 跟随底部：添加到 #chat 末尾随消息滚动；固定顶部/固定底部：添加到 body
      if (c.pos === 'follow-bottom') {
        var chatEl = pd.getElementById('chat');
        if (chatEl) {
          chatEl.appendChild(w);
        } else {
          pd.body.appendChild(w);
        }
      } else {
        pd.body.appendChild(w);
      }

      // 清理旧 wrapper
      try {
        var allW = pd.querySelectorAll('#ac-statusbar-wrapper');
        for (var ow = 0; ow < allW.length; ow++) {
          if (allW[ow] !== w) {
            // 清理旧wrapper中残留的settingsOverlay
            var oldOv = allW[ow].querySelector('#settingsOverlay');
            if (oldOv) oldOv.remove();
            allW[ow].remove();
          }
        }
      } catch(e) {}

      // 仅首次注入脚本到父页面（避免重复执行导致闪烁和状态丢失）
      if (sCode && !scriptInjected) {
        var s = pd.createElement('script');
        // 关键：必须声明为 module，让压缩后的短变量名（const e=...,t=...）
        // 留在独立模块作用域内，不泄漏到全局与 jQuery/其他插件的全局变量冲突，
        // 否则浏览器抛出 "Identifier 't' has already been declared" 导致整段脚本失效。
        // （源 HTML 中本就是 <script type="module">，提取注入时不能丢这个属性。）
        s.type = 'module';
        s.textContent = sCode;
        pd.head.appendChild(s);
        scriptInjected = true;
      }

      // 移动端修正 overlay
      applyMobileOverlayFixes();

      // 通知 app 已完成重注入（让 app 恢复折叠状态、迁移 overlay 等）
      try {
        if (scriptInjected && typeof pd.defaultView.__ub_on_reinject === 'function') {
          pd.defaultView.__ub_on_reinject();
        }
      } catch(e) {}

      injecting = false;
    } catch(e) {
      console.error('[统一状态栏] 注入失败:', e.message);
      injecting = false;
    }
  }

  // 移动端：修正 overlay/popup 样式（inline style 确保不被父页面CSS覆盖）
  function applyMobileOverlayFixes() {
    if (window.innerWidth > 600) return;
    try {
      var ovs = pd.querySelectorAll('.settings-overlay, .nsfw-overlay, .panel-overlay');
      for (var oi = 0; oi < ovs.length; oi++) {
        ovs[oi].style.alignItems = 'flex-start';
        ovs[oi].style.paddingTop = '60px';
        ovs[oi].style.paddingBottom = '20px';
      }
      var pops = pd.querySelectorAll('.settings-popup, .nsfw-popup, .panel-popup');
      for (var pi = 0; pi < pops.length; pi++) {
        pops[pi].style.maxHeight = '70vh';
      }
    } catch(e) {}
  }

  try { pd.defaultView.__ub_inject = inject; } catch(e) {}

  // ===== 齿轮拖动（支持触屏 + 移动端安全区） =====
  (function() {
    var n = 0;
    var iv = setInterval(function() {
      n++;
      var g = pd.getElementById('ac-persistent-settings');
      if (g) {
        clearInterval(iv);
        var down = false, sx, sy, sl, st, dragMoved = false;
        g.style.cursor = 'grab'; g.style.userSelect = 'none'; g.style.touchAction = 'none';
        function dragStart(ex, ey) {
          down = true; dragMoved = false; g.style.cursor = 'grabbing';
          sx = ex; sy = ey;
          var r = g.getBoundingClientRect(); sl = r.left; st = r.top;
          g.style.position = 'fixed'; g.style.right = 'auto'; g.style.bottom = 'auto';
          g.style.left = sl + 'px'; g.style.top = st + 'px';
        }
        function dragMove(ex, ey) {
          if (!down) return;
          var dx = ex - sx, dy = ey - sy;
          if (Math.abs(dx) > 4 || Math.abs(dy) > 4) dragMoved = true;
          if (dragMoved) {
            g.style.left = (sl + dx) + 'px';
            g.style.top = (st + dy) + 'px';
          }
        }
        function dragEnd(e) {
          if (!down) return; down = false; g.style.cursor = 'grab';
          if (dragMoved) {
            try { ls.setItem('statusbar-gear-pos', JSON.stringify({x: parseInt(g.style.left)||0, y: parseInt(g.style.top)||0})); } catch(e) {}
            // 阻止拖拽后的 click 事件打开设置
            if (e) { e.stopPropagation(); e.preventDefault(); }
            g.addEventListener('click', function(ce) { ce.stopPropagation(); ce.preventDefault(); }, {once: true, capture: true});
          }
          dragMoved = false; // 复位：避免遗留 true 让后续 touchmove 误判为拖拽中
        }
        g.addEventListener('mousedown', function(e) { dragStart(e.clientX, e.clientY); e.preventDefault(); });
        g.addEventListener('touchstart', function(e) { if (e.touches.length === 1) { dragStart(e.touches[0].clientX, e.touches[0].clientY); /* 不 preventDefault，让 click 能正常触发 */ } }, {passive: true});
        pd.addEventListener('mousemove', function(e) { dragMove(e.clientX, e.clientY); });
        // 关键：未处于拖拽中（down=false）时立即返回，不调用 preventDefault。
        // dragMoved 在拖拽后被置 true 且 dragEnd 未复位，若此处不按 down 短路，
        // 一次拖拽后 dragMoved 永远为 true，后续任意 touchmove 都会 preventDefault，
        // 整个酒馆页面将无法滑动，直至刷新重置闭包（移动端拖齿轮后页面冻结的根因）。
        pd.addEventListener('touchmove', function(e) { if (!down) return; if (e.touches.length === 1) { dragMove(e.touches[0].clientX, e.touches[0].clientY); if (dragMoved) e.preventDefault(); } }, {passive: false});
        pd.addEventListener('mouseup', dragEnd);
        pd.addEventListener('touchend', dragEnd);
        try {
          var saved = ls.getItem('statusbar-gear-pos');
          if (saved) {
            var pos = JSON.parse(saved);
            g.style.position = 'fixed'; g.style.right = 'auto'; g.style.bottom = 'auto';
            g.style.left = pos.x + 'px'; g.style.top = pos.y + 'px';
          }
        } catch(e) {}
      }
      if (n > 80) clearInterval(iv);
    }, 150);
  })();

  // ===== 首次注入 =====
  inject();

  // ===== #chat 清空守卫：跟随底部刷新丢栏的根本修复 =====
  // follow-bottom 模式下 wrapper 是 #chat 的子节点；酒馆加载/切换聊天时会清空 #chat 子节点
  // （clearChat），把 wrapper 一并移除。刷新页面重进「同一聊天」不触发 CHAT_CHANGED（chat_id 未变），
  // wrapper 丢失后既无重建路径、主脚本 updateWrapperStyle 也会因 wrapper 为空早退 → 状态栏永久消失，
  // 仅切到固定顶部重刷才恢复（固定模式 wrapper 在 body，不受 #chat 清空影响）。
  // 守卫：观察 #chat，wrapper 从文档中消失时自动 inject() 重建。位置无关——切到固定布局时 wrapper
  // 在 body，仍能被 getElementById 找到，不会误重建；生成期消息 append 时 wrapper 在场，回调为空操作。
  (function() {
    var chat = pd.getElementById('chat');
    if (!chat || !pd.defaultView || !pd.defaultView.MutationObserver) return;
    var guard = new pd.defaultView.MutationObserver(function() {
      if (!scriptInjected) return;
      if (!pd.getElementById('ac-statusbar-wrapper')) {
        try { inject(); } catch(e) {}
      }
    });
    guard.observe(chat, { childList: true });
  })();

  // ===== 监听聊天变化 =====
  try {
    if (typeof eventOn === 'function' && typeof tavern_events !== 'undefined') {
      eventOn(tavern_events.CHAT_CHANGED, function() {
        setTimeout(function() {
          // #chat 清空守卫已负责重建丢失的 wrapper；此处仅在 wrapper 仍丢失时兜底重建，
          // 否则仅重渲染（避免与守卫重复重建导致抖动）。原按 c.pos 分支的写法依赖 loader 侧
          // 与主脚本可能不一致的位置缓存，改为按 wrapper 是否在场判断更稳健。
          if (!pd.getElementById('ac-statusbar-wrapper')) {
            inject();
          } else if (scriptInjected) {
            try {
              if (typeof pd.defaultView.__ub_on_reinject === 'function') {
                pd.defaultView.__ub_on_reinject();
              }
            } catch(e) {}
          }
        }, 600);
      });
    }
  } catch(e) {}

  // ===== 监听窗口大小变化 / 屏幕旋转（防抖处理） =====
  // 关键：主脚本注入后由主脚本统一处理 resize，loader 不再修改 wrapper CSS，避免双重 cssText 赋值导致手机端闪烁
  (function() {
    var resizeTimer;
    function onResize() {
      if (resizeTimer) clearTimeout(resizeTimer);
      resizeTimer = setTimeout(function() {
        resizeTimer = null;
        if (!scriptInjected) {
          // 主脚本尚未注入时，loader 自己处理
          var w = pd.getElementById('ac-statusbar-wrapper');
          if (w) {
            var c = cfg();
            w.style.cssText = wrapCSS(c);
          }
          applyMobileOverlayFixes();
        }
        // 主脚本注入后，由 handleResize（__ub_on_resize）统一处理，避免与 loader 重复修改样式
        try { if (typeof pd.defaultView.__ub_on_resize === 'function') pd.defaultView.__ub_on_resize(); } catch(e) {}
      }, 200);
    }
    pd.defaultView.addEventListener('resize', onResize);
    pd.defaultView.addEventListener('orientationchange', function() { setTimeout(onResize, 300); });

    // 移动端 visualViewport 监听：地址栏伸缩、键盘弹出/收起时重新计算布局
    if (pd.defaultView.visualViewport) {
      var _vvResizeTimerL;
      pd.defaultView.visualViewport.addEventListener('resize', function() {
        if (_vvResizeTimerL) clearTimeout(_vvResizeTimerL);
        _vvResizeTimerL = setTimeout(function() {
          _vvResizeTimerL = null;
          if (!scriptInjected) {
            var w2 = pd.getElementById('ac-statusbar-wrapper');
            if (w2) {
              var c2 = cfg();
              w2.style.cssText = wrapCSS(c2);
            }
            applyMobileOverlayFixes();
          }
          // 主脚本注入后，由 handleResize（__ub_on_resize）统一处理，避免与 loader 重复修改样式
          try { if (typeof pd.defaultView.__ub_on_resize === 'function') pd.defaultView.__ub_on_resize(); } catch(e) {}
        }, 150);
      });
    }
  })();

  console.log('[统一状态栏] ✅ 就绪');
});
